import{_ as a}from"./chunks/theme.ngAvV2nn.js";import{_ as t,a as r,c as o,j as n}from"./chunks/framework.DVzkjf-b.js";const m=JSON.parse(`{"title":"Rethinking Education with AI","description":"Keith Williams's questions about independent learning, source-grounded AI, and how to spend human attention on decisions that need it.","frontmatter":{"title":"Rethinking Education with AI","description":"Keith Williams's questions about independent learning, source-grounded AI, and how to spend human attention on decisions that need it."},"headers":[],"relativePath":"research.md","filePath":"research.md"}`),s={name:"research.md"};function i(h,e,d,c,l,u){return r(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="rethinking-education-with-ai" tabindex="-1">Rethinking Education with AI <a class="header-anchor" href="#rethinking-education-with-ai" aria-label="Permalink to &quot;Rethinking Education with AI&quot;">​</a></h1><p><strong>If AI can produce the assignment, what do we want the student to learn?</strong> I come back to that question in class when a student shows me something that works. I want to know what they would try if I changed one requirement.</p><p>A related question shows up in my engineering work. An AI system gives someone a plausible answer. What would it take for that person to check the source, spot an error, and correct it?</p><p>This is a research agenda, <strong>not a list of completed experiments or peer-reviewed findings</strong>.</p><h2 id="can-you-use-what-you-learned-somewhere-new" tabindex="-1">Can you use what you learned somewhere new? <a class="header-anchor" href="#can-you-use-what-you-learned-somewhere-new" aria-label="Permalink to &quot;Can you use what you learned somewhere new?&quot;">​</a></h2><p>In my programming Studios, an AI coach can offer hints, run checks, and help a learner move forward. At the next checkpoint I can change the rule of a game or give the student a new source to inspect. How much of what they learned travels with them?</p><p>I&#39;d like to compare how students explain a decision, debug unfamiliar code, or solve a related problem with different amounts of help. A successful demo gives us a place to start. An answer about learning would require fair comparisons and a consistent way to judge the follow-up. <a href="/teaching/when-ai-helps-write-the-code">Read the classroom feature</a> · <a href="/teaching/studio-field-notes">Explore the research behind the Studio</a></p><h2 id="what-should-count-as-evidence-of-learning" tabindex="-1">What should count as evidence of learning? <a class="header-anchor" href="#what-should-count-as-evidence-of-learning" aria-label="Permalink to &quot;What should count as evidence of learning?&quot;">​</a></h2><p>The questions a student asks, the tests they choose, and the reasons they give for revising their work may tell us something the finished program, essay, or design leaves out. I&#39;d like to know which of those observations are useful to another instructor, how consistently teachers can interpret them, and how much time collection takes away from practice.</p><h2 id="building-knowledge-a-reader-can-check" tabindex="-1">Building knowledge a reader can check <a class="header-anchor" href="#building-knowledge-a-reader-can-check" aria-label="Permalink to &quot;Building knowledge a reader can check&quot;">​</a></h2><p><img src="'+a+'" alt="A magnifying glass enlarges a marked spot on layers of blue tracing paper."></p><p>Imagine two documents that disagree about the same event. A search system can return both. A reader still needs to see which passage supports each claim, where the records disagree, and what remains uncertain. My research starts with that reader&#39;s problem.</p><p>The systems series explores document processing, graph and vector retrieval, software tests, and deciding when a person should review a result. It distinguishes what I have built from the larger architecture I propose to evaluate. <a href="/research/systems/">Read the research series and technical case studies</a></p><p>For a closer look at engineering decisions, start with the <a href="/research/systems/metavis-evidence-and-evaluation">MetaVis case study</a>. For the proposed research methods and questions open for faculty discussion, see the <a href="/research/systems/dissertation-proposal">preliminary doctoral proposal</a> and <a href="/research/systems/literature-and-faculty">literature and faculty reading map</a>.</p><h2 id="how-do-we-work-with-ai-responsibly" tabindex="-1">How do we work with AI responsibly? <a class="header-anchor" href="#how-do-we-work-with-ai-responsibly" aria-label="Permalink to &quot;How do we work with AI responsibly?&quot;">​</a></h2><p>An assistant that can act across tools creates a different relationship from a chatbot that suggests text. How much direction does it need? What should it verify? How do we recover when it gets something wrong? <a href="/life-tracker">Life Tracker</a> describes how I keep a record of what happened. <a href="https://github.com/kaw393939/ordo" target="_blank" rel="noreferrer">Ordo</a> documents the design of a broader system for human-directed AI work.</p><p>I also want practical AI education to reach beyond the university. My earlier EverydayAI Newark concept explored how community members could learn with real projects. <a href="/about">Read about my background and community work</a></p>',17)])])}const g=t(s,[["render",i]]);export{m as __pageData,g as default};
